{
  "name": "get_rf_path_param",
  "confidence": "medium",
  "docstring": "Fetches or updates the RF parameter entry for a given path, switching RF paths or consulting calibration state when required.",
  "subsystem": "rf",
  "var_renames": {
    "v4": "param_ptr",
    "v6": "path_entry",
    "v7": "active_param_ptr",
    "v8": "rf_info_ptr",
    "v9": "rf_path_active",
    "v10": "rf_ctrl_word",
    "v11": "rf_info_obj",
    "a2": "path_ctx",
    "a3": "path_idx"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "RF path table entry active parameter/context pointer"
    },
    {
      "offset": 4,
      "meaning": "RF path table entry saved parameter/context pointer"
    },
    {
      "offset": 8,
      "meaning": "RF path table entry saved-pointer valid flag"
    },
    {
      "offset": 1,
      "meaning": "off_116EF0 RF path state byte at +1; active/selected indicator"
    },
    {
      "offset": 56,
      "meaning": "a2 context flags: bit 0x200000 controls whether param_ptr is saved into path_entry[1]"
    },
    {
      "offset": 36,
      "meaning": "off_116EE0 per-path entries base (28-byte stride)"
    },
    {
      "offset": 46,
      "meaning": "off_116EE0 per-path entry flag byte at offset 10 from entry base"
    },
    {
      "offset": 190,
      "meaning": "off_116EE0 current RF path index"
    },
    {
      "offset": 208,
      "meaning": "off_116EE0 RF control word; bit 0 participates in path-switching condition"
    }
  ]
}
